import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";

export type RecordActivityTaskHeartbeatInput = {
  /**
   * The taskToken of the ActivityTask. taskToken is generated by the service and should be treated
   * as an opaque value. If the task is passed to another process, its taskToken must also be
   * passed. This enables it to provide its progress and respond with results.
   */
  taskToken: string;
  /** If specified, contains details about the progress of the task. */
  details?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const recordActivityTaskHeartbeatInputSchema: Schema<RecordActivityTaskHeartbeatInput> =
  s.object<RecordActivityTaskHeartbeatInput>(
    {
      taskToken: s.string(),
      details: s.optional(s.string()),
    },
    { additionalProperties: s.json() },
  );
